      _withFinalizeGate(config.systemPrompt ?? _currentMode.systemPrompt),
      contextSection: formatProjectContext(_contextFiles),
      skillsSection: formatSkillsForPrompt(
        _enabledSkills,
        touchedPaths: _touchedPaths,
